{
  "sql": "SELECT rango_retraso, COUNT(*) AS pedidos, ROUND(100.0 * SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_2_o_menos, ROUND(100.0 * SUM(CASE WHEN rango_retraso = 'a_tiempo' THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_a_tiempo FROM vw_retraso_por_rango WHERE rango_retraso IN ('a_tiempo', '1-3', '4-7', '8-14') GROUP BY rango_retraso HAVING pct_2_o_menos >= 2 * pct_a_tiempo ORDER BY rango_retraso ASC LIMIT 1"
}

